'use strict';

// MODULES //

var constantFunction = require( '@stdlib/utils/constant-function' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );
var exp = require( '@stdlib/math/base/special/exp' );
var pow = require( '@stdlib/math/base/special/pow' );
var PI = require( '@stdlib/constants/float64/pi' );
var SQRT2 = require( '@stdlib/constants/float64/sqrt-two' );
var PINF = require( '@stdlib/constants/float64/pinf' );


// MAIN //

/**
* Returns a function for evaluating the probability density function (PDF) for a half-normal distribution.
*
* @param {PositiveNumber} sigma - scale parameter
* @returns {Function} function to evaluate the probability density function
*
* @example
* var pdf = factory( 2.0 );
* var y = pdf( 1.0 );
* // returns 0.3520653267642996
*
* y = pdf( 0.0 );
* // returns 0.3989422804014327
*/
function factory( sigma ) {
	var s2;
	var A;
	if (
		isnan( sigma ) ||
		sigma < 0.0
	) {
		return constantFunction( NaN );
	}
	if ( sigma === 0.0 ) {
		return pdf;
	}
	s2 = pow( sigma, 2.0 );
	A = SQRT2 / ( sigma * sqrt( PI ) );
	return pdf;

	/**
	* Evaluates the probability density function (PDF) for a half-normal distribution.
	*
	* @private
	* @param {number} x - input value
	* @returns {number} evaluated probability density function
	*
	* @example
	* var y = pdf( 2.0 );
	* // returns <number>
	*/
	function pdf( x ) {
		if ( isnan( x ) ) {
			return NaN;
		}
		if ( x < 0.0 ) {
			return 0.0;
		}
		if ( sigma === 0.0 ) {
			return ( x === 0.0 ) ? PINF : 0.0;
		}
		return A * exp( -pow( x, 2.0 ) / ( 2.0 * s2 ) );
	}
}


// EXPORTS //

module.exports = factory;
